let welcomeBriefing=null,briefingActive=null;
function englishNarrator(){if(typeof window==='undefined'||!window.speechSynthesis)return null;const voices=window.speechSynthesis.getVoices().filter(v=>/^en(?:-|_)/i.test(v.lang));return voices.find(v=>v.default)||voices.find(v=>/matua|mitchell|daniel|david|alex|male/i.test(v.name))||voices[0]||null}
function stopBriefing(){const active=briefingActive;if(!active)return;briefingActive=null;if(active.video&&!active.video.paused)active.video.pause?.();if(active.timer)clearInterval(active.timer);active.timer=null;active.playing=false;if(active.button)active.button.textContent=active.time>=(active.duration||30)?'Replay 30s':'Play 30s';window.speechSynthesis?.cancel()}
function briefingMarkup(preview,video=false){const duration=Number(preview.duration)||30,label=video?`${preview.presenter||'Geoff'} / YOUR GUIDE`:'GEOFF IN 30 SECONDS',seconds=Math.round(duration),clock=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;return `<div class="briefing-heading"><div><span>${esc(label)}</span><h3>${video&&!preview.race?'Your Stakes Day guide':`Race ${preview.race} briefing`}</h3></div><span class="briefing-duration">${clock}</span></div>${video?`<video class="welcome-video" controls playsinline preload="none" poster="${esc(preview.poster)}" aria-label="${esc(preview.presenter||'Geoff')} introduces Geoffs Guide"><source src="${esc(preview.video)}" type="video/mp4"><track kind="captions" srclang="en" label="English captions" src="${esc(preview.captions||(preview.race?'':'assets/geoff-welcome.vtt'))}"></video>`:`<div class="briefing-stage"><div class="briefing-host"><div class="briefing-geoff"><img src="assets/geoff-source.jpg" alt="Geoff" width="590" height="1280"></div><span>GEOFF<small>Synthetic presenter</small></span></div><h4 class="briefing-scene-title">${esc(preview.scenes[0].title)}</h4><p class="briefing-scene-caption">${esc(preview.scenes[0].caption)}</p><p class="briefing-assumptions"></p></div><progress class="briefing-progress" max="30" value="0" aria-label="Thirty-second briefing progress"></progress>`}<div class="briefing-controls">${video?'':'<button class="briefing-play" type="button">Play 30s</button>'}<button class="briefing-sound" type="button" aria-pressed="true">Checking narration…</button><span class="briefing-status" aria-live="polite">${preview.voice?.recorded?`${preview.presenter||'Geoff'} · synthetic narration`:'Captioned · synthetic presenter'}</span></div><details class="briefing-transcript"><summary>Read the preview &amp; sources</summary>${preview.scenes.map(s=>`<p>${esc(s.narration)}${s.assumptions?`<small>${esc(s.assumptions)}</small>`:''}</p>`).join('')}${(preview.opinions||[]).map(o=>`<p><b>${esc(o.name)} · ${esc(o.horse)}</b><small>${esc(o.why)} Ground: ${esc(o.ground)} Run: ${esc(o.run)}</small><a href="${esc(o.url)}" target="_blank" rel="noopener">Published view ↗</a></p>`).join('')}${preview.audio?`<a href="${esc(preview.audio)}" target="_blank" rel="noopener">Listen to narration only ↗</a>`:''}${(preview.sources||[]).map(s=>`<a href="${esc(typeof s==='string'?s:s.url)}" target="_blank" rel="noopener">${esc(typeof s==='string'?'Source ↗':s.title+' ↗')}</a>`).join('')}</details>`}
function bindBriefing(box,preview){
 const state={box,preview,duration:Number(preview.duration)||30,time:0,lastScene:-1,playing:false,sound:true,video:box.querySelector('video'),button:box.querySelector('.briefing-play'),soundButton:box.querySelector('.briefing-sound')};box._briefing=state;
 const updateVoice=()=>{if(preview.voice?.recorded){state.soundButton.hidden=true;return}const voice=englishNarrator();state.soundButton.disabled=!voice;state.soundButton.textContent=voice?(state.sound?'Narration · on':'Narration · off'):'Captions only';state.soundButton.setAttribute('aria-pressed',String(!!voice&&state.sound))};
 function sceneAt(time,speak=true){if(time>=state.duration)speak=false;const i=time>=state.duration?preview.scenes.length-1:Math.max(0,preview.scenes.findIndex(s=>time>=s.start&&time<s.end)),scene=preview.scenes[i];if(!scene||i===state.lastScene)return;state.lastScene=i;if(!state.video){box.querySelector('.briefing-scene-title').textContent=scene.title;box.querySelector('.briefing-scene-caption').textContent=scene.caption;box.querySelector('.briefing-assumptions').textContent=scene.assumptions||''}const voice=englishNarrator(),Ctor=window.SpeechSynthesisUtterance;if(speak&&state.sound&&!preview.voice?.recorded&&voice&&Ctor&&state.playing){window.speechSynthesis.cancel();const utterance=new Ctor(scene.narration);utterance.voice=voice;utterance.lang=voice.lang||'en-US';utterance.rate=Math.max(.9,Math.min(1.35,scene.narration.split(/\s+/).length/((scene.end-scene.start)*2.6)));utterance.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))box.querySelector('.briefing-status').textContent='Audio unavailable; captions continue.'};window.speechSynthesis.speak(utterance)}}
 function begin(){if(briefingActive&&briefingActive!==state)stopBriefing();briefingActive=state;state.playing=true;state.lastScene=-1;sceneAt(state.time);}
 if(state.video){state.video.addEventListener('play',()=>{state.time=state.video.currentTime||0;begin()});state.video.addEventListener('timeupdate',()=>{state.time=state.video.currentTime||0;if(state.playing)sceneAt(state.time)});state.video.addEventListener('pause',()=>{if(briefingActive===state)stopBriefing()});state.video.addEventListener('ended',()=>{if(briefingActive===state)stopBriefing()});state.video.addEventListener('seeked',()=>{state.lastScene=-1;if(state.playing)sceneAt(state.video.currentTime||0)})}
 else state.button.onclick=()=>{if(state.playing){stopBriefing();return}if(state.time>=state.duration)state.time=0;begin();state.button.textContent='Pause';const start=Date.now()-state.time*1000;state.timer=setInterval(()=>{state.time=Math.min(state.duration,(Date.now()-start)/1000);box.querySelector('progress').value=state.time;if(state.time>=state.duration){stopBriefing();return}sceneAt(state.time)},200)};
 state.soundButton.onclick=()=>{state.sound=!state.sound;updateVoice();if(briefingActive===state){window.speechSynthesis?.cancel();state.lastScene=-1;sceneAt(state.time)}};updateVoice();window.speechSynthesis?.addEventListener?.('voiceschanged',updateVoice,{once:true});
}
function renderRaceBriefing(){if(!race)return;for(const box of [document.getElementById('raceBriefing'),document.getElementById('formRaceBriefing')]){if(!box)continue;const savedPreview=lateMail?.previews?.[String(race.number)],media=lateMail?.raceVideos?.[String(race.number)],preview=savedPreview&&media&&media.preparedAt===savedPreview.preparedAt?{...savedPreview,...media,scenes:savedPreview.scenes.filter(s=>!(media.omittedNarration||[]).includes(s.narration))}:savedPreview,jump=Date.parse(lateMail?.selections?.[String(race.number)]?.startAt||''),now=Date.now(),valid=preview?.race===race.number&&preview.date===data.date&&Date.parse(preview.preparedAt)<Date.parse(preview.jumpAt)&&Date.parse(preview.preparedAt)>=Date.parse(preview.jumpAt)-600000;
 if(!valid){if(box._briefing&&briefingActive===box._briefing)stopBriefing();box._briefing=null;box.dataset.previewKey='';box.innerHTML=`<div class="briefing-locked"><span>GEOFF’S 30-SECOND RACE PREVIEW</span><p>${Number.isFinite(jump)&&now<jump-600000?`Prepared after the ten-minute check, around ${mailClock(new Date(jump-600000).toISOString())}.`:Number.isFinite(jump)&&now>=jump?'No saved ten-minute preview is available for this race.':'Waiting for a successful saved ten-minute check.'}</p></div>`;continue}
 const key=preview.runKey+'-'+preview.preparedAt+'-'+(preview.video||preview.audio||'captions')+'-'+(lateMail?.raceVideoJobs?.[String(race.number)]?.state||'');if(box.dataset.previewKey===key)continue;if(box._briefing&&briefingActive===box._briefing)stopBriefing();box.dataset.previewKey=key;const job=lateMail?.raceVideoJobs?.[String(race.number)],videoNotice=!preview.video&&job?`<p class="video-job-status" role="status">${job.state==='failed'?'Video unavailable · saved briefing below':job.state==='video'?'Geoff’s animation is still rendering at ElevenLabs.':'Geoff’s race video is being prepared.'}${preview.audio?' Narration is ready to play below.':''}</p>`:'';
 box.innerHTML=(preview.video&&preview.recordingNote?`<p class="briefing-saved">${esc(preview.recordingNote)}</p>`:'')+videoNotice+(preview.audio&&!preview.video?`<div class="briefing-heading"><h3>Geoff’s saved Race ${preview.race} briefing</h3></div><audio controls preload="none" src="${esc(preview.audio)}" aria-label="Geoff’s saved pre-race narration"></audio>${preview.recordingNote?`<p class="briefing-saved">${esc(preview.recordingNote)}</p>`:''}<details class="briefing-transcript"><summary>Read the saved briefing &amp; sources</summary>${preview.scenes.map(s=>`<p>${esc(s.narration)}</p>`).join('')}${(preview.sources||[]).map(s=>`<a href="${esc(s)}" target="_blank" rel="noopener">Source ↗</a>`).join('')}</details>`:briefingMarkup(preview,!!preview.video))+`<p class="briefing-saved">Saved before jump · ${mailDate(preview.preparedAt)} · editorial views are attributed, not recorded guest voices.</p>`;if(!(preview.audio&&!preview.video))bindBriefing(box,preview);
}}
const welcomeDismissKey='gg-welcome-dismissed-v1';
function initBriefings(){
 const dialog=document.getElementById('welcomeDialog'),box=document.getElementById('welcomeBriefing');let previousFocus=null;
 const close=()=>{stopBriefing();dialog.querySelector('video')?.pause?.();try{localStorage.setItem(welcomeDismissKey,'1')}catch{}if(dialog.close)dialog.close();else dialog.removeAttribute('open');previousFocus?.focus?.()};
 const open=()=>{previousFocus=document.activeElement;if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');document.getElementById('dismissWelcome').focus?.()};
 document.getElementById('dismissWelcome').onclick=close;document.getElementById('startGuide').onclick=close;
 dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect?.();if(r&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))close()}});
 document.getElementById('openWelcome').onclick=open;
 fetch('welcome-preview.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(preview=>{welcomeBriefing=preview;box.innerHTML=briefingMarkup(preview,true);bindBriefing(box,preview);let dismissed=false;try{dismissed=localStorage.getItem(welcomeDismissKey)==='1'}catch{}if(!dismissed)open()}).catch(()=>{box.innerHTML='<p class="mail-quiet">The welcome is unavailable. Your form guide is ready.</p>'});
}
